// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new PoCGame(address(this), 0); vm.stopPrank(); }
    function testFuzz_property(address tokenOwner, uint256 tokens) public {
        tokenOwner = address(uint160(bound(uint160(tokenOwner), 1, type(uint160).max - 1)));
        FailingToken tok = new FailingToken();
        address __invmut_eoa = address(uint160(0xE0A));
        vm.prank(__invmut_eoa);
        bool ok = c.transferAnyERC20Token(address(tok), tokenOwner, tokens);
        // The token's transfer reports failure (returns false), so c must report false.
        assertTrue(!ok);
    }
}

contract FailingToken {
    function transfer(address to, uint256 tokens) public returns (bool success) {
        to; tokens;
        return false;
    }
}
